-- CANDIDAT RECETTE UNIQUEMENT, NON VALIDÉ : ne pas installer tant que realtime.messages ne reçoit pas les messages.
-- Ne jamais créer une partition du service géré ni modifier ses propriétaires pour contourner les restrictions.
DO $preflight$
DECLARE probe text:='waarwi:recette-probe:'||gen_random_uuid()::text;
BEGIN
 PERFORM realtime.send(jsonb_build_object('table','recette_probe'),'data_changed',probe,true);
 IF NOT EXISTS(SELECT 1 FROM realtime.messages WHERE topic=probe AND event='data_changed') THEN
 RAISE EXCEPTION 'Service Realtime de recette indisponible : aucune notification enregistrée.' USING ERRCODE='55000';
 END IF;
 DELETE FROM realtime.messages WHERE topic=probe;
END $preflight$;
CREATE SCHEMA IF NOT EXISTS waarwi_sync;
REVOKE ALL ON SCHEMA waarwi_sync FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION waarwi_sync.notify_statement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tenant_ids uuid[];
  changed boolean;
  affected_tenant uuid;
  row_source text;
  topic_mode text := tg_argv[0];
  tenant_key text := case when tg_table_name = 'tenants' then 'id' else 'tenant_id' end;
  notice jsonb := jsonb_build_object('table', tg_table_name);
begin
  if tg_op = 'INSERT' then
    row_source := 'select * from new_rows';
  elsif tg_op = 'DELETE' then
    row_source := 'select * from old_rows';
  elsif tg_table_name = 'tenants' then
    -- La présence ne modifie pas les informations affichées par les modules.
    row_source := 'select n.* from new_rows n left join old_rows o on o.id = n.id
      where (to_jsonb(n) - ''last_active_at'') is distinct from (to_jsonb(o) - ''last_active_at'')';
  else
    row_source := 'select * from new_rows union all select * from old_rows';
  end if;

  if topic_mode in ('shared', 'platform') then
    execute 'select exists (' || row_source || ')' into changed;
    if changed then perform realtime.send(notice, 'data_changed', 'waarwi:' || topic_mode, true); end if;
    return null;
  end if;

  if tg_table_name = 'mt_wholesaler_services' then
    execute format('select array_agg(distinct w.tenant_id) from (%s) r
      join public.mt_wholesalers w on w.id = r.wholesaler_id', row_source) into tenant_ids;
  else
    execute format('select array_agg(distinct r.%I) from (%s) r', tenant_key, row_source) into tenant_ids;
  end if;
  if tenant_ids is null then return null; end if;

  foreach affected_tenant in array tenant_ids loop
    if affected_tenant is not null then
      perform realtime.send(notice, 'data_changed', 'waarwi:tenant:' || affected_tenant::text, true);
    elsif tg_table_name = 'tenant_messages' then
      perform realtime.send(notice, 'data_changed', 'waarwi:shared', true);
    end if;
  end loop;
  if topic_mode = 'tenant_and_platform' then
    perform realtime.send(notice, 'data_changed', 'waarwi:platform', true);
  end if;
  return null;
end;
$function$;
REVOKE ALL ON FUNCTION waarwi_sync.notify_statement() FROM PUBLIC,anon,authenticated,service_role;
CREATE POLICY "Waarwi private change notices" ON realtime.messages AS PERMISSIVE FOR SELECT TO authenticated USING (((extension = 'broadcast'::text) AND (topic = ( SELECT realtime.topic() AS topic)) AND (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND (p.is_active IS NOT FALSE) AND (((( SELECT realtime.topic() AS topic) = 'waarwi:shared'::text) AND ((p.tenant_id IS NOT NULL) OR (p.role = 'super_admin'::text))) OR ((( SELECT realtime.topic() AS topic) = 'waarwi:platform'::text) AND (p.role = 'super_admin'::text)) OR (( SELECT realtime.topic() AS topic) = ('waarwi:tenant:'::text || (p.tenant_id)::text))))))));
